CREATE INDEX "sav_operator_message_idx" ON "audit_logs" USING btree ("entity_id",("technical_metadata"->>'messageId'),("technical_metadata"->>'kind'),"created_at" DESC NULLS LAST,"id" DESC NULLS LAST) WHERE "audit_logs"."action"='sav_intake_operator_command' and "audit_logs"."entity_type"='sav_intake_operator_command';--> statement-breakpoint
CREATE INDEX "sav_operator_pending_idx" ON "audit_logs" USING btree (("technical_metadata"->>'state'),"created_at","id") WHERE "audit_logs"."action"='sav_intake_operator_command' and "audit_logs"."entity_type"='sav_intake_operator_command' and "audit_logs"."technical_metadata"->>'kind'='resume';